lib='''def mark_partial_copies(grid, marker=1):
    """Mark with marker the cells where a non-uniform row deviates from a matching row on background cells (an incomplete copy of a full row/block)."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for i in range(h):
        if len(set(grid[i])) == 1:
            continue  # uniform rows are templates, never partial copies
        for j in range(h):
            if i == j:
                continue
            diff = [c for c in range(w) if grid[i][c] != grid[j][c]]
            if 0 < len(diff) < w and all(grid[i][c] == bg for c in diff):
                for c in diff:
                    out[i][c] = marker
    return out
'''
